import React from 'react';
import { motion } from 'framer-motion';

const SIG_LABELS = {
  lstm_direction: 'LSTM Dir. Head  ×0.45',
  rsi:            'RSI Signal      ×0.25',
  macd_cross:     'MACD Cross      ×0.20',
  ma_crossover:   'MA Cross        ×0.10',
};

const EnsemblePanel = ({ ensemble }) => {
  if (!ensemble) return null;
  const { signals, probability, is_high_confidence, is_neutral, direction } = ensemble;
  const isBull = direction === 'UP' || probability >= 0.5;

  const tierLabel = is_high_confidence
    ? { text: 'HIGH CONFIDENCE', color: 'var(--green)', bg: 'rgba(0,232,122,0.08)' }
    : is_neutral
    ? { text: 'NEUTRAL — signals conflicting', color: 'var(--muted)', bg: 'rgba(90,106,130,0.06)' }
    : { text: 'MODERATE', color: 'var(--amber)', bg: 'rgba(245,166,35,0.08)' };

  return (
    <motion.div className="card ensemble-card"
      initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.1 }}
    >
      <div className="card-title">
        <div className="card-ico ico-g">🎯</div>
        <span className="card-title-text">Direction Ensemble</span>
      </div>

      <div className="signal-list">
        {Object.entries(signals || {}).map(([key, sig], i) => {
          const bull = sig.value >= 0.5;
          const pct  = sig.value * 100;
          return (
            <motion.div key={key} className="signal-row"
              initial={{ opacity: 0, x: -12 }} animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.12 + i * 0.06 }}
            >
              <span className="sig-name" style={{ width: 185 }}>
                {SIG_LABELS[key] || key}
              </span>
              <div className="sig-bar">
                <motion.div
                  className={`sig-fill ${bull ? 'bull' : 'bear'}`}
                  initial={{ width: 0 }}
                  animate={{ width: `${pct}%` }}
                  transition={{ duration: 0.9, delay: 0.18 + i * 0.06 }}
                />
              </div>
              <span className="sig-val" style={{ color: bull ? 'var(--green)' : 'var(--red)' }}>
                {pct.toFixed(0)}%
              </span>
            </motion.div>
          );
        })}
      </div>

      {/* Composite result */}
      <div style={{
        marginTop: 14, padding: '10px 14px', borderRadius: 8,
        background: tierLabel.bg,
        border: `1px solid ${tierLabel.color}22`,
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{
            fontFamily: "'Orbitron', monospace", fontSize: 13, fontWeight: 700,
            color: isBull ? 'var(--green)' : 'var(--red)'
          }}>
            {isBull ? '↑ BULLISH' : '↓ BEARISH'}
          </span>
          <span style={{
            fontFamily: "'JetBrains Mono', monospace", fontSize: 10,
            color: 'var(--dim)'
          }}>
            Composite: {(probability * 100).toFixed(1)}%
          </span>
        </div>
        <div style={{
          marginTop: 6, fontFamily: "'JetBrains Mono', monospace",
          fontSize: 10, color: tierLabel.color
        }}>
          {tierLabel.text}
        </div>
        {is_neutral && (
          <div style={{ marginTop: 4, fontSize: 10, color: 'var(--muted)', fontFamily: "'JetBrains Mono', monospace" }}>
            ⚠️ Score in neutral zone (0.47–0.53). Exclude from accuracy metrics — use HIGH_CONF calls only.
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default EnsemblePanel;
